// ── STYLES ─────────────────────────────────────────────────────────────
const styles = `
  @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,600;0,700;1,400&family=Plus+Jakarta+Sans:wght@300;400;500;600&display=swap');
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
  body, #root { background: #fdfcf9; color: #1a1714; font-family: 'Plus Jakarta Sans', sans-serif; min-height: 100vh; }
  ::-webkit-scrollbar { width: 4px; }
  ::-webkit-scrollbar-track { background: #f5f0e8; }
  ::-webkit-scrollbar-thumb { background: #d4c9b8; border-radius: 2px; }

  .dish-card {
    background: #fff; border: 1.5px solid #ece6db; border-radius: 12px;
    padding: 16px 18px; cursor: pointer; transition: all .2s;
    display: flex; align-items: center; justify-content: space-between; gap: 12px;
    box-shadow: 0 1px 3px rgba(0,0,0,.04);
  }
  .dish-card:hover { border-color: #c2622a; box-shadow: 0 4px 16px rgba(194,98,42,.12); transform: translateY(-2px); }

  .btn {
    display: inline-flex; align-items: center; gap: 8px; padding: 10px 22px;
    background: #c2622a; color: #fff; font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 13px; font-weight: 600; border: none; border-radius: 10px;
    cursor: pointer; transition: all .2s; letter-spacing: .01em;
  }
  .btn:hover { background: #a8501f; transform: translateY(-1px); box-shadow: 0 4px 14px rgba(194,98,42,.35); }

  .btn-ghost {
    background: transparent; border: 1.5px solid #ddd6ca; color: #888;
    padding: 8px 16px; font-size: 13px; font-family: 'Plus Jakarta Sans', sans-serif;
    border-radius: 10px; cursor: pointer; transition: all .15s;
    display: inline-flex; align-items: center; gap: 6px; font-weight: 500;
  }
  .btn-ghost:hover { border-color: #c2622a; color: #c2622a; background: #fdf3ed; }

  .step-num {
    width: 28px; height: 28px; min-width: 28px; background: #c2622a; color: #fff;
    border-radius: 50%; display: flex; align-items: center; justify-content: center;
    font-size: 11px; font-weight: 700;
  }

  .ad-unit {
    width: 100%; border: 1.5px dashed #e0d8ce; border-radius: 10px;
    background: #faf7f3; overflow: hidden; cursor: pointer; transition: border-color .2s;
  }
  .ad-unit:hover { border-color: #c2622a; }
  .ad-label { font-size: 9px; letter-spacing: .12em; color: #c8bfb0; text-transform: uppercase; text-align: center; padding: 5px 0 0; font-family: monospace; }

  @media (max-width: 768px) {
    .dish-grid { grid-template-columns: 1fr !important; }
    .region-grid { grid-template-columns: 1fr !important; }
    .stat-row { flex-wrap: wrap; }
    .ing-grid { grid-template-columns: 1fr !important; }
  }
`;

// ── NO AI CALLS — fully hardcoded site ─────────────────────────────

// ── RESPONSIVE AD UNIT ─────────────────────────────────────────────────
function AdUnit({ style }) {
  const [hover, setHover] = useState(false);
  const [mob, setMob] = useState(() => typeof window !== 'undefined' && window.innerWidth <= 768);
  useEffect(() => {
    const fn = () => setMob(window.innerWidth <= 768);
    window.addEventListener('resize', fn);
    fn();
    return () => window.removeEventListener('resize', fn);
  }, []);
  const h = mob ? 58 : 90;
  const divH = mob ? 26 : 38;
  return (
    <div onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)}
      style={{ width:"100%", border:`1.5px dashed ${hover?"#c2622a":"#e0d8ce"}`, borderRadius:10, background:"#faf7f3", overflow:"hidden", cursor:"pointer", transition:"border-color .2s", marginBottom:8, ...style }}>
      <div style={{ fontSize:9, letterSpacing:".12em", color:"#c8bfb0", textTransform:"uppercase", textAlign:"center", padding:"5px 0 0", fontFamily:"monospace" }}>Advertisement</div>
      <div style={{ height:h, display:"flex", alignItems:"center", justifyContent:"center", gap:mob?10:14, padding:`0 ${mob?14:24}px`, position:"relative" }}>
        <div style={{ position:"absolute", top:0, left:0, right:0, height:1, background:`linear-gradient(90deg,transparent,#c2622a 40%,#c2622a 60%,transparent)`, opacity:hover?.2:.08, transition:"opacity .2s" }} />
        <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:3, flexShrink:0 }}>
          <span style={{ fontSize:mob?14:18, opacity:.25 }}>📢</span>
          <span style={{ fontFamily:"monospace", fontSize:10, color:"#c8bfb0" }}>{mob?"320 × 50":"728 × 90"}</span>
        </div>
        <div style={{ width:1, height:divH, background:"#e8e0d4", flexShrink:0 }} />
        <div style={{ display:"flex", flexDirection:"column", gap:3 }}>
          <span style={{ fontFamily:"monospace", fontSize:mob?9:10, color:"#c8bfb0" }}>{mob?"Mobile banner — insert ad tag here":"Leaderboard — insert ad tag here"}</span>
          <span style={{ fontFamily:"monospace", fontSize:9, color:"#ddd5c8" }}>Responsive · switches format by breakpoint</span>
        </div>
      </div>
    </div>
  );
}


// ── REGION MAP ─────────────────────────────────────────────────────────
// ── RECIPE INSPIRATION CAROUSEL ────────────────────────────────────────

function getRandomRecipes(keys, n) {
  const shuffled = [...keys].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, n).map(k => ({ key: k, ...RECIPE_DB[k] }));
}

function RecipeInspiration({ recipes: initialRecipes, pool, title }) {
  const { navigate } = useAppNavigate();
  const [recipes, setRecipes] = useState(initialRecipes);

  const shuffle = () => {
    const allKeys = pool || Object.keys(RECIPE_DB);
    const shuffled = [...allKeys].sort(() => Math.random() - 0.5).slice(0, 3);
    setRecipes(shuffled.map(k => ({ key: k, ...RECIPE_DB[k] })));
  };

  if (!recipes || recipes.length === 0) return null;

  return (
    <div style={{ marginTop:32, marginBottom:8 }}>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:16, flexWrap:"wrap", gap:8 }}>
        <div>
          <h2 style={{ fontFamily:"Fraunces", fontSize:"clamp(18px,2.5vw,26px)", fontWeight:700, color:"#1a1714", margin:0 }}>{title}</h2>
          <p style={{ fontSize:13, color:"#9a9088", margin:"4px 0 0" }}>Tap a recipe to get cooking</p>
        </div>
        <button onClick={shuffle}
          style={{ background:"#fdf3ed", border:"1.5px solid #e8c9b0", borderRadius:8, padding:"8px 16px", fontSize:13, fontWeight:600, color:"#c2622a", cursor:"pointer", fontFamily:"Plus Jakarta Sans", display:"flex", alignItems:"center", gap:6 }}>
          ↻ Randomise
        </button>
      </div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit, minmax(220px, 1fr))", gap:16 }}>
        {recipes.filter(Boolean).map((recipe, i) => {
          const region = REGIONS.find(r => r.countries?.includes(recipe.country));
          return (
            <div key={i} onClick={() => navigate(`/${region?.id || ""}/${slugify(recipe.country)}/${slugify(recipe.key || recipe.name)}`)}
              style={{ background:"#fff", border:"1.5px solid #ece6db", borderRadius:12, overflow:"hidden", cursor:"pointer", transition:"transform .15s, box-shadow .15s" }}
              onMouseEnter={e => { e.currentTarget.style.transform="translateY(-2px)"; e.currentTarget.style.boxShadow="0 6px 20px rgba(0,0,0,.08)"; }}
              onMouseLeave={e => { e.currentTarget.style.transform="none"; e.currentTarget.style.boxShadow="none"; }}>
              <div style={{ width:"100%", height:160, overflow:"hidden", background:"#f0e8e0" }}>
                <img src={recipe.image} alt={`Authentic ${recipe.country} ${recipe.name} recipe`} style={{ width:"100%", height:"100%", objectFit:"cover", display:"block" }} />
              </div>
              <div style={{ padding:"12px 14px 14px" }}>
                <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:6 }}>
                  <span style={{ fontSize:14 }}>{COUNTRY_DISHES[recipe.country]?.flag}</span>
                  <span style={{ fontSize:11, color:"#9a9088", fontFamily:"Plus Jakarta Sans", fontWeight:500 }}>{recipe.country}</span>
                </div>
                <div style={{ fontFamily:"Fraunces", fontSize:16, fontWeight:700, color:"#1a1714", lineHeight:1.3, marginBottom:4 }}>{recipe.name}</div>
                <div style={{ fontSize:12, color:"#c2622a", fontWeight:600, fontFamily:"Plus Jakarta Sans" }}>View recipe →</div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// Hook to access navigate from child components
function useAppNavigate() {
  return { navigate: (path) => { window.history.pushState({}, '', path); window.scrollTo(0,0); window.dispatchEvent(new PopStateEvent('popstate')); } };
}

function RegionMap({ onSelectRegion }) {
  const [hovered, setHovered] = useState(null);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const loadMap = () => {
      const container = document.getElementById('ra-world-map');
      if (!container) return;
      if (!window.d3 || !window.topojson) return;
      const d3 = window.d3;
      const topojson = window.topojson;
      const w = container.offsetWidth;
      if (!w) return;
      container.innerHTML = '';
      container.style.height = '0px';

      const COUNTRY_REGION = {
        8:'europe',20:'europe',40:'europe',56:'europe',70:'europe',100:'europe',
        112:'europe',191:'europe',203:'europe',208:'europe',233:'europe',246:'europe',
        250:'europe',276:'europe',292:'europe',300:'europe',336:'europe',348:'europe',
        352:'europe',372:'europe',380:'europe',428:'europe',438:'europe',440:'europe',
        442:'europe',470:'europe',492:'europe',498:'europe',499:'europe',528:'europe',
        578:'europe',616:'europe',620:'europe',642:'europe',674:'europe',688:'europe',
        703:'europe',705:'europe',724:'europe',752:'europe',756:'europe',804:'europe',
        807:'europe',826:'europe',831:'europe',832:'europe',833:'europe',
        268:'europe',643:'europe',51:'europe',383:'europe',
        28:'north_america',44:'north_america',52:'north_america',84:'north_america',
        124:'north_america',136:'north_america',188:'north_america',192:'north_america',
        212:'north_america',214:'north_america',222:'north_america',304:'north_america',
        308:'north_america',312:'north_america',316:'north_america',320:'north_america',
        332:'north_america',340:'north_america',388:'north_america',474:'north_america',
        484:'north_america',500:'north_america',531:'north_america',533:'north_america',
        534:'north_america',535:'north_america',558:'north_america',570:'north_america',
        591:'north_america',652:'north_america',659:'north_america',660:'north_america',
        662:'north_america',663:'north_america',670:'north_america',780:'north_america',
        796:'north_america',840:'north_america',850:'north_america',
        32:'south_america',68:'south_america',76:'south_america',152:'south_america',
        170:'south_america',218:'south_america',238:'south_america',239:'south_america',
        254:'south_america',328:'south_america',600:'south_america',604:'south_america',
        740:'south_america',858:'south_america',862:'south_america',
        12:'africa',24:'africa',72:'africa',86:'africa',108:'africa',120:'africa',
        132:'africa',140:'africa',148:'africa',174:'africa',175:'africa',178:'africa',
        180:'africa',204:'africa',231:'africa',232:'africa',262:'africa',266:'africa',
        270:'africa',288:'africa',324:'africa',384:'africa',404:'africa',426:'africa',
        430:'africa',434:'africa',450:'africa',454:'africa',466:'africa',478:'africa',
        480:'africa',504:'africa',508:'africa',516:'africa',562:'africa',566:'africa',
        624:'africa',638:'africa',646:'africa',654:'africa',686:'africa',694:'africa',
        706:'africa',710:'africa',716:'africa',720:'africa',728:'africa',729:'africa',
        732:'africa',736:'africa',768:'africa',788:'africa',800:'africa',818:'africa',
        834:'africa',854:'africa',894:'africa',
        31:'europe',48:'middle_east',196:'middle_east',275:'middle_east',
        364:'middle_east',368:'middle_east',376:'middle_east',400:'middle_east',
        414:'middle_east',422:'middle_east',512:'middle_east',634:'middle_east',
        682:'middle_east',760:'middle_east',784:'middle_east',792:'middle_east',
        887:'middle_east',
        4:'asia',50:'asia',64:'asia',96:'asia',104:'asia',116:'asia',
        144:'asia',156:'asia',158:'asia',344:'asia',356:'asia',360:'asia',
        392:'asia',398:'asia',408:'asia',410:'asia',417:'asia',418:'asia',
        446:'asia',458:'asia',462:'asia',496:'asia',524:'asia',586:'asia',
        608:'asia',626:'asia',702:'asia',704:'asia',762:'asia',764:'asia',
        795:'asia',860:'asia',
        36:'oceania',90:'oceania',184:'oceania',242:'oceania',258:'oceania',
        296:'oceania',316:'oceania',520:'oceania',540:'oceania',548:'oceania',
        554:'oceania',570:'oceania',574:'oceania',580:'oceania',581:'oceania',
        583:'oceania',585:'oceania',598:'oceania',612:'oceania',772:'oceania',
        776:'oceania',798:'oceania',876:'oceania',882:'oceania',
      };

      const REGIONS = {
        europe:        { color:'#4a6fa5', label:'🏰 Europe' },
        north_america: { color:'#c2622a', label:'🌎 North America' },
        south_america: { color:'#2a7a4a', label:'🌿 South America' },
        africa:        { color:'#b5820a', label:'🌍 Africa' },
        middle_east:   { color:'#8b4513', label:'🕌 Middle East' },
        asia:          { color:'#6a3d8a', label:'🏯 Asia' },
        oceania:       { color:'#2a8a7a', label:'🦘 Oceania' },
      };

      const ANTARCTICA = 10;

      // Use a sphere-fitted projection so map fills container edge to edge
      const projection = d3.geoNaturalEarth1().rotate([-10, 0]);
      const path = d3.geoPath().projection(projection);

      // Fit projection tightly to all land (excluding Antarctica)
      const getRegionByCoords = (d, path, projection) => {
        const centroid = path.centroid(d);
        if (!projection.invert) return null;
        const projected = projection.invert(centroid);
        if (!projected) return null;
        const [lon, lat] = projected;
        if (lon > -82 && lon < -33 && lat > -60 && lat < 7) return 'south_america';
        if (lon > -80 && lon < -60 && lat >= 7 && lat < 12) return 'south_america';
        if (lon > -170 && lon < -60) return 'north_america';
        if (lon > 25 && lon < 65 && lat > 10 && lat < 42) return 'middle_east';
        if (lon > -25 && lon < 45 && lat > 35 && lat < 72) return 'europe';
        if (lon > 100 && lat < -10) return 'oceania';
        if (lon > 60 && lon < 180 && lat > -15 && lat < 55) return 'asia';
        if (lon > -20 && lon < 55 && lat > -35 && lat < 38) return 'africa';
        return null;
      };

      fetch('https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json')
        .then(r => r.json())
        .then(world => {
          const countries = topojson.feature(world, world.objects.countries);
          const land = {
            type: 'FeatureCollection',
            features: countries.features.filter(d => +d.id !== ANTARCTICA)
          };

          // Fit projection symmetrically — use fitSize so D3 centres automatically
          const h = Math.round(w * 0.52);
          projection.fitSize([w, h], land);
          container.style.height = h + 'px';

          const svg = d3.select(container).append('svg')
            .attr('width', w).attr('height', h)
            .style('display', 'block');

          svg.append('rect').attr('width', w).attr('height', h).attr('fill', 'none');

          const tip = document.getElementById('ra-map-tip');

          // Explode MultiPolygon features into individual polygons so each
          // gets coloured by its own centroid (fixes France/French Guiana etc.)
          const exploded = [];
          land.features.forEach(f => {
            if (f.geometry.type === 'MultiPolygon') {
              f.geometry.coordinates.forEach(coords => {
                exploded.push({
                  ...f,
                  geometry: { type: 'Polygon', coordinates: coords }
                });
              });
            } else {
              exploded.push(f);
            }
          });

          svg.selectAll('.country')
            .data(exploded)
            .enter().append('path')
            .attr('d', path)
            .attr('fill', d => {
              // Check coordinates first ONLY for South America to fix French Guiana
              const centroid = path.centroid(d);
              const projected = projection.invert ? projection.invert(centroid) : null;
              if (projected) {
                const [lon, lat] = projected;
                if (lon > -82 && lon < -33 && lat > -60 && lat < 7) return REGIONS.south_america.color;
                if (lon > -80 && lon < -60 && lat >= 7 && lat < 12) return REGIONS.south_america.color;
              }
              // Use ID lookup for everything else
              const rid = COUNTRY_REGION[+d.id];
              if (rid) return REGIONS[rid].color;
              // Coordinate fallback for truly unmapped countries
              return getRegionByCoords(d, path, projection)
                ? REGIONS[getRegionByCoords(d, path, projection)].color
                : '#c8bfb0';
            })
            .attr('stroke', '#fdf8f3')
            .attr('stroke-width', 0.5)
            .style('cursor', 'pointer')
            .style('transition', 'opacity .15s')
            .on('mouseover', function(event, d) {
              const rid = getRegionByCoords(d, path, projection) || COUNTRY_REGION[+d.id];
              if (!rid) return;
              d3.select(this).attr('opacity', 0.75);
              if (tip) { tip.textContent = REGIONS[rid].label; tip.style.display = 'block'; }
            })
            .on('mousemove', function(event) {
              if (tip) { tip.style.left = (event.clientX + 14) + 'px'; tip.style.top = (event.clientY - 36) + 'px'; }
            })
            .on('mouseout', function(event, d) {
              d3.select(this).attr('opacity', 1);
              if (tip) tip.style.display = 'none';
            })
            .on('click', function(event, d) {
              const rid = getRegionByCoords(d, path, projection) || COUNTRY_REGION[+d.id];
              if (!rid) return;
              if (tip) tip.style.display = 'none';
              onSelectRegion(rid);
            });

          svg.append('path')
            .datum(topojson.mesh(world, world.objects.countries, (a,b) => a !== b && +a.id !== ANTARCTICA && +b.id !== ANTARCTICA))
            .attr('fill', 'none').attr('stroke', '#fdf8f3').attr('stroke-width', 0.4).attr('d', path);
        })
        .catch(() => {});
    };

    const loadScripts = (cb) => {
      if (window.d3 && window.topojson) { cb(); return; }
      const s1 = document.createElement('script');
      s1.src = 'https://cdnjs.cloudflare.com/ajax/libs/d3/7.8.5/d3.min.js';
      s1.onload = () => {
        const s2 = document.createElement('script');
        s2.src = 'https://cdnjs.cloudflare.com/ajax/libs/topojson/3.0.2/topojson.min.js';
        s2.onload = cb;
        document.head.appendChild(s2);
      };
      document.head.appendChild(s1);
    };

    // Small delay on first render so mobile layout has settled
    let resizeTimer;
    const handleResize = () => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(loadMap, 100);
    };

    loadScripts(() => {
      setTimeout(loadMap, 100);
      window.addEventListener('resize', handleResize);
    });

    return () => {
      window.removeEventListener('resize', handleResize);
      clearTimeout(resizeTimer);
    };
  }, []);

  return (
    <div>
      <div style={{ textAlign:"center", marginBottom:16, paddingTop:8 }}>
        <div style={{ display:"inline-block", background:"#fdf3ed", borderRadius:100, padding:"6px 16px", fontSize:11, fontWeight:700, color:"#c2622a", letterSpacing:".08em", textTransform:"uppercase", fontFamily:"Plus Jakarta Sans", marginBottom:12 }}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" style={{display:"inline",verticalAlign:"middle",marginRight:4}}>
                <circle cx="14" cy="12" r="8" stroke="#c2622a" strokeWidth="2" fill="none"/>
                <path d="M6 12 Q14 8 22 12" stroke="#c2622a" strokeWidth="1.5" fill="none"/>
                <path d="M6 12 Q14 16 22 12" stroke="#c2622a" strokeWidth="1.5" fill="none"/>
                <line x1="14" y1="4" x2="14" y2="20" stroke="#c2622a" strokeWidth="1.5"/>
                <line x1="3" y1="4" x2="3" y2="20" stroke="#c2622a" strokeWidth="2" strokeLinecap="round"/>
                <line x1="1" y1="4" x2="1" y2="9" stroke="#c2622a" strokeWidth="1.5" strokeLinecap="round"/>
                <line x1="5" y1="4" x2="5" y2="9" stroke="#c2622a" strokeWidth="1.5" strokeLinecap="round"/>
                <path d="M1 9 Q3 13 5 9" stroke="#c2622a" strokeWidth="1.5" fill="none"/>
              </svg> World Cuisine Explorer
        </div>
        <h1 style={{ fontFamily:"Fraunces", fontSize:"clamp(26px,4vw,48px)", fontWeight:700, color:"#1a1714", marginBottom:8 }}>
          What would you like to cook?
        </h1>
        <p style={{ fontSize:"clamp(13px,1.5vw,16px)", color:"#9a9088", maxWidth:480, margin:"0 auto 24px", lineHeight:1.7 }}>
          Choose a region to explore its most beloved dishes and get the full recipe.
        </p>
      </div>

      {/* Interactive world map */}
      <div id="ra-world-map" style={{ width:"100%", borderRadius:12, overflow:"hidden", background:"transparent", marginBottom:24 }}></div>
      <div id="ra-map-tip" style={{ position:"fixed", background:"rgba(26,23,20,.9)", color:"#fff", padding:"6px 14px", borderRadius:8, fontSize:13, fontWeight:600, pointerEvents:"none", display:"none", zIndex:999, whiteSpace:"nowrap" }}></div>

      {/* First ad */}
      <AdUnit />

      {/* Region buttons */}
      <div className="region-grid" style={{ marginTop:24, display:"grid", gridTemplateColumns:"repeat(auto-fit, minmax(260px, 1fr))", gap:12, marginBottom:28 }}>
        {REGIONS.map(region => (
          <div key={region.id} onClick={() => onSelectRegion(region.id)}
            onMouseEnter={e => e.currentTarget.style.borderColor=region.color}
            onMouseLeave={e => e.currentTarget.style.borderColor="#ece6db"}
            style={{ background:"#fff", border:"1.5px solid #ece6db", borderRadius:12, padding:"16px 18px", cursor:"pointer", transition:"border-color .2s, box-shadow .2s" }}>
            <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:8 }}>
              <span style={{ fontSize:22 }}>{region.emoji}</span>
              <span style={{ fontFamily:"Fraunces", fontSize:17, fontWeight:700, color:"#1a1714" }}>{region.name}</span>
            </div>
            <p style={{ fontSize:13, color:"#6a6058", lineHeight:1.6, marginBottom:10 }}>{region.description}</p>
            <div style={{ display:"flex", flexWrap:"wrap", gap:4 }}>
              {region.countries.slice(0,5).map(c => (
                <span key={c} style={{ fontSize:11, background:"#faf7f3", border:"1px solid #ece6db", borderRadius:6, padding:"2px 8px", color:"#9a9088" }}>
                  {COUNTRY_DISHES[c]?.flag} {c}
                </span>
              ))}
              {region.countries.length > 5 && <span style={{ fontSize:11, color:"#c8bfb0", padding:"2px 4px" }}>+{region.countries.length - 5} more</span>}
            </div>
          </div>
        ))}
      </div>

      {/* Second ad */}
      <AdUnit />

      {/* Recipe inspiration */}
      <RecipeInspiration recipes={getRandomRecipes(Object.keys(RECIPE_DB), 3)} pool={Object.keys(RECIPE_DB)} title="Recipe Inspiration" />

      {/* Third ad */}
      <AdUnit style={{ marginTop:24 }} />
    </div>
  );
}

function RegionView({ regionId, onBack, onSelectCountry }) {
  const region = REGIONS.find(r => r.id === regionId);
  if (!region) return null;
  const regionRecipeKeys = Object.keys(RECIPE_DB).filter(k => region.countries.includes(RECIPE_DB[k].country));
  return (
    <div style={{ maxWidth:720, margin:"0 auto" }}>
      <button className="btn-ghost" onClick={onBack} style={{ marginBottom:24 }}>← All Regions</button>
      <div style={{ marginBottom:8 }}>
        <div style={{ fontSize:44, marginBottom:8 }}>{region.emoji}</div>
        <h1 style={{ fontFamily:"Fraunces", fontSize:32, fontWeight:700, color:"#1a1714", marginBottom:6 }}>{region.name}</h1>
        <p style={{ fontSize:14, color:"#9a9088", marginBottom:6 }}>{region.description}</p>
        <div style={{ height:3, width:40, background:region.color, borderRadius:2, marginBottom:24 }} />
      </div>
      <AdUnit />
      <div style={{ marginTop:24, marginBottom:28 }}>
        <p style={{ fontSize:11, color:"#b8b0a8", marginBottom:14, letterSpacing:".08em", textTransform:"uppercase", fontWeight:600 }}>Select a country</p>
        <div style={{ display:"flex", flexWrap:"wrap", gap:10 }}>
          {region.countries.map(country => (
            <button key={country} onClick={() => onSelectCountry(country)}
              style={{ display:"inline-flex", alignItems:"center", gap:10, background:"#fff", border:`1.5px solid #ece6db`, borderRadius:12, padding:"12px 18px", cursor:"pointer", fontSize:14, color:"#1a1714", fontFamily:"Plus Jakarta Sans", transition:"all .15s", boxShadow:"0 1px 4px rgba(0,0,0,.05)", fontWeight:500 }}
              onMouseEnter={e => { e.currentTarget.style.borderColor=region.color; e.currentTarget.style.background=region.light; e.currentTarget.style.boxShadow=`0 4px 14px ${region.color}20`; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor="#ece6db"; e.currentTarget.style.background="#fff"; e.currentTarget.style.boxShadow="0 1px 4px rgba(0,0,0,.05)"; }}>
              <span style={{ fontSize:24 }}>{COUNTRY_DISHES[country]?.flag || "🌍"}</span>
              <span>{country}</span>
            </button>
          ))}
        </div>
      </div>
      <AdUnit />
      <RecipeInspiration recipes={getRandomRecipes(regionRecipeKeys, 3)} pool={regionRecipeKeys} title="Recipe Inspiration" />
      <AdUnit style={{ marginTop:24 }} />
    </div>
  );
}

// ── COUNTRY VIEW ───────────────────────────────────────────────────────
function CountryView({ country, onBack, onSelectDish }) {
  const preset = COUNTRY_DISHES[country];
  const flag = preset?.flag || "🌍";
  const dishes = preset?.dishes || [];
  const countryRecipeKeys = Object.keys(RECIPE_DB).filter(k => RECIPE_DB[k].country === country);

  return (
    <div style={{ maxWidth:700, margin:"0 auto" }}>
      <button className="btn-ghost" onClick={onBack} style={{ marginBottom:24 }}>← Back</button>
      <div style={{ marginBottom:8 }}>
        <div style={{ fontSize:44, marginBottom:8 }}>{flag}</div>
        <h1 style={{ fontFamily:"Fraunces", fontSize:30, fontWeight:700, color:"#1a1714", marginBottom:6 }}>{country}</h1>
        <p style={{ fontSize:14, color:"#9a9088", marginBottom:20 }}>Choose a dish to view the full recipe</p>
      </div>
      <AdUnit />
      <div style={{ marginTop:24, marginBottom:28 }}>
        <div className="dish-grid" style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
          {dishes.map((dish,i) => (
            <div key={i} className="dish-card" onClick={() => onSelectDish(dish)}>
              <div>
                <div style={{ fontSize:14, fontWeight:600, color:"#1a1714", marginBottom:3 }}>{dish}</div>
                <div style={{ fontSize:11, color:"#b8b0a8", fontWeight:500 }}>View recipe →</div>
              </div>
              <span style={{ fontSize:16, color:"#ddd5c8" }}>→</span>
            </div>
          ))}
        </div>
      </div>
      <AdUnit />
      <RecipeInspiration recipes={getRandomRecipes(countryRecipeKeys, 3)} pool={countryRecipeKeys} title="Recipe Inspiration" />
      <AdUnit style={{ marginTop:24 }} />
    </div>
  );
}

// ── RECIPE VIEW ────────────────────────────────────────────────────────
function RecipeView({ country, dish, onBack, navigate }) {
  const [recipe, setRecipe] = useState(null);
  const [loading, setLoading] = useState(true);
  const flag = COUNTRY_DISHES[country]?.flag || "🌍";

  useEffect(() => {
    setLoading(false);
    if (RECIPE_DB[dish]) { setRecipe(RECIPE_DB[dish]); }
    else { setRecipe({ error: true }); }
  }, [dish, country]);

  return (
    <div style={{ maxWidth:700, margin:"0 auto" }}>
      <button className="btn-ghost" onClick={onBack} style={{ marginBottom:24 }}>← Back to {country || recipeCountry}</button>
      <AdUnit />
      <div style={{ marginTop:24 }}>
        {loading ? (
          <div style={{ textAlign:"center", padding:"60px 0" }}>
            <div className="spinner" style={{ width:24, height:24, margin:"0 auto 14px" }} />
            <p style={{ fontSize:14, color:"#b8b0a8", fontStyle:"italic" }}>Preparing your recipe…</p>
          </div>
        ) : recipe && !recipe.error ? (
          <div>
            <div style={{ marginBottom:28 }}>
              {country && <div style={{ display:"inline-block", background:"#fdf3ed", borderRadius:100, padding:"4px 12px", fontSize:11, color:"#c2622a", fontWeight:600, letterSpacing:".06em", textTransform:"uppercase", marginBottom:12 }}>
                {country}
              </div>}
              <h1 style={{ fontFamily:"Fraunces", fontSize:32, fontWeight:700, color:"#1a1714", marginBottom:10, lineHeight:1.2 }}>{recipe.name}</h1>
              {recipe.story && <p style={{ fontSize:13, color:"#b8b0a8", fontStyle:"italic", marginBottom:10, lineHeight:1.7 }}>{recipe.story}</p>}
              <p style={{ fontSize:15, color:"#6a6058", lineHeight:1.85, marginBottom:16 }}>{recipe.description}</p>
              {recipe.image && (
                <div style={{ marginBottom:20, borderRadius:12, overflow:"hidden", boxShadow:"0 2px 12px rgba(0,0,0,.08)", background:"#f0e8e0" }}>
                  <img src={recipe.image} alt={`Authentic ${recipe.country} ${recipe.name} recipe`}
                    style={{ width:"100%", height:260, objectFit:"cover", display:"block" }}
                    crossOrigin="anonymous"
                  />
                </div>
              )}
              <div className="stat-row" style={{ display:"flex", gap:10, flexWrap:"wrap" }}>
                {[{l:"Prep",v:recipe.prepTime},{l:"Cook",v:recipe.cookTime},{l:"Serves",v:recipe.serves},{l:"Difficulty",v:recipe.difficulty}].map(({l,v})=>(
                  <div key={l} style={{ background:"#fff", border:"1.5px solid #ece6db", borderRadius:10, padding:"8px 16px", textAlign:"center", minWidth:80, boxShadow:"0 1px 3px rgba(0,0,0,.04)" }}>
                    <div style={{ fontSize:10, color:"#b8b0a8", letterSpacing:".07em", textTransform:"uppercase", marginBottom:3, fontWeight:600 }}>{l}</div>
                    <div style={{ fontSize:13, fontWeight:600, color:"#1a1714" }}>{v}</div>
                  </div>
                ))}
              </div>
            </div>
            <div style={{ background:"#fff", border:"1.5px solid #ece6db", borderRadius:14, padding:24, marginBottom:12, boxShadow:"0 1px 4px rgba(0,0,0,.04)" }}>
              <h3 style={{ fontFamily:"Fraunces", fontSize:19, marginBottom:18, color:"#1a1714" }}>Ingredients</h3>
              <div className="ing-grid" style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:"0 20px" }}>
                {(recipe.ingredients||[]).map((ing,i)=>(
                  <div key={i} style={{ display:"flex", gap:10, paddingBottom:9, borderBottom:"1px solid #f5f0e8", marginBottom:1, alignItems:"baseline" }}>
                    <span style={{ fontSize:12, fontWeight:700, color:ACCENT, minWidth:60, flexShrink:0 }}>{ing.amount}</span>
                    <span style={{ fontSize:13, color:"#5a5048" }}>{ing.item}</span>
                  </div>
                ))}
              </div>
            </div>
            <div style={{ background:"#fff", border:"1.5px solid #ece6db", borderRadius:14, padding:24, marginBottom:12, boxShadow:"0 1px 4px rgba(0,0,0,.04)" }}>
              <h3 style={{ fontFamily:"Fraunces", fontSize:19, marginBottom:20, color:"#1a1714" }}>Method</h3>
              <div style={{ display:"flex", flexDirection:"column", gap:16 }}>
                {(recipe.steps||[]).map((step,i)=>(
                  <div key={i} style={{ display:"flex", gap:14, alignItems:"flex-start" }}>
                    <div className="step-num">{i+1}</div>
                    <p style={{ fontSize:14, color:"#5a5048", lineHeight:1.8, paddingTop:3 }}>{step}</p>
                  </div>
                ))}
              </div>
            </div>
            {recipe.tip && (
              <div style={{ background:"#fdf8f3", border:"1.5px solid #f0e4d4", borderRadius:14, padding:18, borderLeft:`4px solid ${ACCENT}`, marginBottom:12 }}>
                <div style={{ fontSize:11, color:ACCENT, letterSpacing:".08em", textTransform:"uppercase", fontWeight:700, marginBottom:6 }}>Chef's Tip</div>
                <p style={{ fontSize:14, color:"#6a6058", lineHeight:1.75 }}>{recipe.tip}</p>
              </div>
            )}
            <div style={{ marginTop:20 }}><AdUnit /></div>

            {/* You may also like */}
            {(() => {
              const currentCountry = recipe.country;
              const region = REGIONS.find(r => r.countries?.includes(currentCountry));
              // Same country first, excluding current recipe
              const sameCountry = Object.keys(RECIPE_DB)
                .filter(k => RECIPE_DB[k].country === currentCountry && RECIPE_DB[k].name !== recipe.name);
              // Fill from same region if needed
              const sameRegion = region
                ? Object.keys(RECIPE_DB).filter(k =>
                    region.countries?.includes(RECIPE_DB[k].country) &&
                    RECIPE_DB[k].country !== currentCountry &&
                    RECIPE_DB[k].name !== recipe.name)
                : [];
              const pool = [...sameCountry, ...sameRegion];
              const shuffled = [...pool].sort(() => Math.random() - 0.5).slice(0, 3);
              if (shuffled.length === 0) return null;
              return (
                <div style={{ marginTop:32 }}>
                  <div style={{ marginBottom:16 }}>
                    <h2 style={{ fontFamily:"Fraunces", fontSize:"clamp(18px,2.5vw,24px)", fontWeight:700, color:"#1a1714", margin:0 }}>You may also like</h2>
                    <p style={{ fontSize:13, color:"#9a9088", margin:"4px 0 0" }}>More recipes you might enjoy</p>
                  </div>
                  <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit, minmax(220px, 1fr))", gap:16 }}>
                    {shuffled.map((key, i) => {
                      const rec = RECIPE_DB[key];
                      const reg = REGIONS.find(r => r.countries?.includes(rec.country));
                      return (
                        <div key={i}
                          onClick={() => navigate(`/${reg?.id || ""}/${slugify(rec.country)}/${slugify(rec.name)}`)}
                          style={{ background:"#fff", border:"1.5px solid #ece6db", borderRadius:12, overflow:"hidden", cursor:"pointer", transition:"transform .15s, box-shadow .15s" }}
                          onMouseEnter={e => { e.currentTarget.style.transform="translateY(-2px)"; e.currentTarget.style.boxShadow="0 6px 20px rgba(0,0,0,.08)"; }}
                          onMouseLeave={e => { e.currentTarget.style.transform="none"; e.currentTarget.style.boxShadow="none"; }}>
                          <div style={{ width:"100%", height:160, overflow:"hidden", background:"#f0e8e0" }}>
                            <img src={rec.image} alt={`Authentic ${rec.country} ${rec.name} recipe`} style={{ width:"100%", height:"100%", objectFit:"cover", display:"block" }} />
                          </div>
                          <div style={{ padding:"12px 14px 14px" }}>
                            <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:6 }}>
                              <span style={{ fontSize:14 }}>{COUNTRY_DISHES[rec.country]?.flag}</span>
                              <span style={{ fontSize:11, color:"#9a9088", fontFamily:"Plus Jakarta Sans", fontWeight:500 }}>{rec.country}</span>
                            </div>
                            <div style={{ fontFamily:"Fraunces", fontSize:16, fontWeight:700, color:"#1a1714", lineHeight:1.3, marginBottom:4 }}>{rec.name}</div>
                            <div style={{ fontSize:12, color:"#c2622a", fontWeight:600, fontFamily:"Plus Jakarta Sans" }}>View recipe →</div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })()}

            {/* Third ad unit */}
            <div style={{ marginTop:24 }}><AdUnit /></div>
          </div>
        ) : (
          <div style={{ textAlign:"center", padding:"40px 0", color:"#b8b0a8" }}>Couldn't load this recipe — please try again.</div>
        )}
      </div>
    </div>
  );
}

// ── MAIN APP ───────────────────────────────────────────────────────────
function slugify(s) {
  if (!s || typeof s !== 'string') return '';
  const map = {'à':'a','á':'a','â':'a','ã':'a','ä':'a','å':'a','è':'e','é':'e','ê':'e','ë':'e','ì':'i','í':'i','î':'i','ï':'i','ò':'o','ó':'o','ô':'o','õ':'o','ö':'o','ù':'u','ú':'u','û':'u','ü':'u','ý':'y','ÿ':'y','ñ':'n','ç':'c','ß':'ss','ž':'z','ż':'z','ź':'z','ł':'l','š':'s','ă':'a','ț':'t','ő':'o','ű':'u','ā':'a','ē':'e','ī':'i','ō':'o','ū':'u'};
  return s.toLowerCase().split('').map(c => map[c] || c).join('').replace(/[^a-z0-9\s-]/g,'').replace(/[\s_]+/g,'-').trim();
}

function unslugify(slug, lookup) {
  if (!slug || !lookup) return null;
  return Object.keys(lookup).find(k =>
    slugify(k) === slug ||
    (lookup[k] && lookup[k].name && slugify(lookup[k].name) === slug)
  ) || null;
}

// ── ROUTER ────────────────────────────────────────────────────────────
function App() {
  const [path, setPath] = useState(() => window.location.pathname);

  useEffect(() => {
    const handler = () => setPath(window.location.pathname);
    window.addEventListener('popstate', handler);
    return () => window.removeEventListener('popstate', handler);
  }, []);

  const navigate = (to) => {
    if (to === -1) { window.history.back(); return; }
    window.history.pushState({}, '', to);
    window.scrollTo(0, 0);
    document.documentElement.scrollTo(0, 0);
    document.body.scrollTo(0, 0);
    setPath(to);
  };

  // Derive view from hierarchical URL: /europe, /europe/italy, /europe/italy/tiramisu
  const safePath = typeof path === 'string' ? path : '/';
  const parts = safePath.split('/').filter(Boolean);
  const infoPages = ['blog','about','contact','privacy','terms'];

  let view = 'regions';
  let selectedRegion = null;
  let selectedCountry = null;
  let selectedDish = null;

  if (parts.length === 0) {
    view = 'regions';
  } else if (infoPages.includes(parts[0])) {
    view = parts[0];
  } else if (parts.length === 1) {
    const region = REGIONS.find(r => r.id === parts[0]);
    if (region) { view = 'region'; selectedRegion = parts[0]; }
  } else if (parts.length === 2) {
    const region = REGIONS.find(r => r.id === parts[0]);
    const country = unslugify(parts[1], COUNTRY_DISHES);
    if (region && country) { view = 'country'; selectedRegion = parts[0]; selectedCountry = country; }
  } else if (parts.length === 3) {
    const region = REGIONS.find(r => r.id === parts[0]);
    const country = unslugify(parts[1], COUNTRY_DISHES);
    const dish = unslugify(parts[2], RECIPE_DB);
    if (region && country && dish) { view = 'recipe'; selectedRegion = parts[0]; selectedCountry = country; selectedDish = dish; }
  }

  const recipeCountry = selectedDish ? RECIPE_DB[selectedDish]?.country : null;
  const countryRegion = selectedCountry ? REGIONS.find(r => r.countries?.includes(selectedCountry)) : null;

  // ── DYNAMIC TITLE & META DESCRIPTION ──────────────────────────────────
  useEffect(() => {
    let title = 'Recipe Atlas — World Cuisine Explorer';
    let description = 'Explore authentic recipes from 44 countries and 7 regions. From Italian carbonara to Georgian khachapuri — discover the world through food.';

    if (view === 'recipe' && selectedDish) {
      const recipe = RECIPE_DB[selectedDish];
      const country = recipeCountry || recipe?.country || '';
      title = `${selectedDish} — Authentic ${country} Recipe | Recipe Atlas`;
      description = recipe?.description
        ? `${recipe.description.replace(/\.+$/, '')}.`
        : `Learn how to make ${selectedDish}, an authentic ${country} dish. Full recipe with ingredients, steps and cultural background.`;
    } else if (view === 'country' && selectedCountry) {
      const flag = COUNTRY_DISHES[selectedCountry]?.flag || '';
      const dishes = COUNTRY_DISHES[selectedCountry]?.dishes?.slice(0, 3).join(', ') || '';
      title = `${selectedCountry} Recipes — Authentic ${selectedCountry} Dishes & Cuisine | Recipe Atlas`;
      description = `Explore authentic ${selectedCountry} recipes including ${dishes} and more. Discover the flavours, techniques and stories behind ${selectedCountry}'s greatest dishes.`;
    } else if (view === 'region' && selectedRegion) {
      const region = REGIONS.find(r => r.id === selectedRegion);
      const regionName = region?.name || selectedRegion;
      const countries = region?.countries?.slice(0, 4).join(', ') || '';
      title = `${regionName} Recipes — Authentic Dishes from ${countries} & More | Recipe Atlas`;
      description = `${region?.description || `Explore the best recipes from ${regionName}`}. Browse authentic dishes from every country in the region.`;
    } else if (view === 'blog') {
      title = 'The Recipe Atlas Blog — Food Stories, Techniques & History';
      description = 'In-depth articles on cooking science, world food history, ingredients and techniques. Stories from the world\'s great food cultures.';
    } else if (view === 'about') {
      title = 'About Recipe Atlas — World Cuisine Explorer';
      description = 'Recipe Atlas celebrates the extraordinary diversity of world cuisine across 44 countries and 7 regions. Learn about our mission and approach.';
    } else if (view === 'contact') {
      title = 'Contact Recipe Atlas — Get in Touch';
      description = 'Get in touch with Recipe Atlas for general enquiries, advertising opportunities, recipe submissions or partnerships. We\'d love to hear from you.';
    } else if (view === 'privacy') {
      title = 'Privacy Policy | Recipe Atlas';
      description = 'Read the Recipe Atlas privacy policy covering data collection, cookies, analytics and advertising.';
    }

    // Ensure title ends cleanly and description ends with full stop
    if (description && !description.endsWith('.')) description += '.';

    document.title = title;

    // Canonical URL
    const canonicalHref = 'https://recipeatlas.co.uk' + window.location.pathname;
    let canonicalTag = document.querySelector('link[rel="canonical"]');
    if (!canonicalTag) {
      canonicalTag = document.createElement('link');
      canonicalTag.rel = 'canonical';
      document.head.appendChild(canonicalTag);
    }
    canonicalTag.href = canonicalHref;

    let metaDesc = document.querySelector('meta[name="description"]');
    if (!metaDesc) {
      metaDesc = document.createElement('meta');
      metaDesc.name = 'description';
      document.head.appendChild(metaDesc);
    }
    metaDesc.content = description;

    // Open Graph tags for social sharing
    const setOG = (property, content) => {
      let tag = document.querySelector(`meta[property="${property}"]`);
      if (!tag) { tag = document.createElement('meta'); tag.setAttribute('property', property); document.head.appendChild(tag); }
      tag.content = content;
    };
    setOG('og:title', title);
    setOG('og:description', description);
    setOG('og:type', 'website');
    setOG('og:url', window.location.href);
    if (view === 'recipe' && selectedDish && RECIPE_DB[selectedDish]?.image) {
      setOG('og:image', RECIPE_DB[selectedDish].image);
    }

    // ── RECIPE JSON-LD STRUCTURED DATA ──────────────────────────────────
    let jsonLd = document.querySelector('script[data-schema="recipe"]');
    if (view === 'recipe' && selectedDish && RECIPE_DB[selectedDish]) {
      const r = RECIPE_DB[selectedDish];
      const schemaData = {
        "@context": "https://schema.org",
        "@type": "Recipe",
        "name": r.name,
        "image": [r.image],
        "description": r.description || '',
        "keywords": `${r.name}, ${r.country} recipe, authentic ${r.country} food, ${r.name.toLowerCase()} recipe`,
        "recipeCategory": "Main Course",
        "recipeCuisine": r.country,
        "prepTime": r.prepTime ? "PT" + r.prepTime.replace(/\s*mins?/i, 'M').replace(/\s*hours?/i, 'H') : undefined,
        "cookTime": r.cookTime ? "PT" + r.cookTime.replace(/\s*mins?/i, 'M').replace(/\s*hours?/i, 'H') : undefined,
        "recipeYield": r.serves ? `${r.serves} servings` : undefined,
        "recipeIngredient": r.ingredients ? r.ingredients.map(ing => `${ing.amount} ${ing.item}`) : [],
        "recipeInstructions": r.steps ? r.steps.map((step, i) => ({
          "@type": "HowToStep",
          "position": i + 1,
          "text": step
        })) : [],
        "author": { "@type": "Organization", "name": "Recipe Atlas" },
        "publisher": { "@type": "Organization", "name": "Recipe Atlas", "url": "https://recipeatlas.co.uk" },
        "url": "https://recipeatlas.co.uk" + window.location.pathname,
      };
      // Remove undefined fields
      Object.keys(schemaData).forEach(k => schemaData[k] === undefined && delete schemaData[k]);
      if (!jsonLd) {
        jsonLd = document.createElement('script');
        jsonLd.type = 'application/ld+json';
        jsonLd.setAttribute('data-schema', 'recipe');
        document.head.appendChild(jsonLd);
      }
      jsonLd.textContent = JSON.stringify(schemaData);
    } else {
      // Remove schema when not on a recipe page
      if (jsonLd) jsonLd.remove();
    }

    // ── BREADCRUMB JSON-LD ───────────────────────────────────────────────
    let breadcrumbLd = document.querySelector('script[data-schema="breadcrumb"]');
    const breadcrumbs = [{ name: 'Home', url: 'https://recipeatlas.co.uk/' }];
    if (view === 'region' && selectedRegion) {
      const region = REGIONS.find(r => r.id === selectedRegion);
      if (region) breadcrumbs.push({ name: region.name + ' Recipes', url: 'https://recipeatlas.co.uk/' + selectedRegion });
    } else if (view === 'country' && selectedCountry) {
      const region = REGIONS.find(r => r.countries?.includes(selectedCountry));
      if (region) breadcrumbs.push({ name: region.name + ' Recipes', url: 'https://recipeatlas.co.uk/' + region.id });
      breadcrumbs.push({ name: selectedCountry + ' Recipes', url: 'https://recipeatlas.co.uk/' + (region?.id || '') + '/' + selectedCountry.toLowerCase().replace(/\s+/g, '-') });
    } else if (view === 'recipe' && selectedDish) {
      const recipe = RECIPE_DB[selectedDish];
      const country = recipeCountry || recipe?.country || '';
      const region = REGIONS.find(r => r.countries?.includes(country));
      if (region) breadcrumbs.push({ name: region.name + ' Recipes', url: 'https://recipeatlas.co.uk/' + region.id });
      breadcrumbs.push({ name: country + ' Recipes', url: 'https://recipeatlas.co.uk/' + (region?.id || '') + '/' + country.toLowerCase().replace(/\s+/g, '-') });
      breadcrumbs.push({ name: selectedDish, url: 'https://recipeatlas.co.uk' + window.location.pathname });
    }
    if (breadcrumbs.length > 1) {
      const breadcrumbSchema = {
        '@context': 'https://schema.org',
        '@type': 'BreadcrumbList',
        'itemListElement': breadcrumbs.map((crumb, i) => ({
          '@type': 'ListItem',
          'position': i + 1,
          'name': crumb.name,
          'item': crumb.url
        }))
      };
      if (!breadcrumbLd) {
        breadcrumbLd = document.createElement('script');
        breadcrumbLd.type = 'application/ld+json';
        breadcrumbLd.setAttribute('data-schema', 'breadcrumb');
        document.head.appendChild(breadcrumbLd);
      }
      breadcrumbLd.textContent = JSON.stringify(breadcrumbSchema);
    } else {
      if (breadcrumbLd) breadcrumbLd.remove();
    }

    // ── WEBSITE + ORGANIZATION SCHEMAS (injected once) ───────────────────
    if (!document.querySelector('script[data-schema="website"]')) {
      const websiteSchema = {
        '@context': 'https://schema.org',
        '@type': 'WebSite',
        'name': 'Recipe Atlas',
        'url': 'https://recipeatlas.co.uk',
        'description': 'Explore authentic recipes from 44 countries and 7 regions. Discover the world through food.',
        'potentialAction': {
          '@type': 'SearchAction',
          'target': { '@type': 'EntryPoint', 'urlTemplate': 'https://recipeatlas.co.uk/?q={search_term_string}' },
          'query-input': 'required name=search_term_string'
        }
      };
      const wsTag = document.createElement('script');
      wsTag.type = 'application/ld+json';
      wsTag.setAttribute('data-schema', 'website');
      wsTag.textContent = JSON.stringify(websiteSchema);
      document.head.appendChild(wsTag);
    }
    if (!document.querySelector('script[data-schema="organization"]')) {
      const orgSchema = {
        '@context': 'https://schema.org',
        '@type': 'Organization',
        'name': 'Recipe Atlas',
        'url': 'https://recipeatlas.co.uk',
        'logo': 'https://recipeatlas.co.uk/favicon.svg',
        'contactPoint': { '@type': 'ContactPoint', 'email': 'contact.jwgroup@proton.me', 'contactType': 'customer support' }
      };
      const orgTag = document.createElement('script');
      orgTag.type = 'application/ld+json';
      orgTag.setAttribute('data-schema', 'organization');
      orgTag.textContent = JSON.stringify(orgSchema);
      document.head.appendChild(orgTag);
    }

  }, [view, selectedDish, selectedCountry, selectedRegion]);
  // ── END DYNAMIC META ───────────────────────────────────────────────────

  const goToRegion      = (rid) => navigate(`/${rid}`);
  const goToCountry     = (c)   => { const r = REGIONS.find(r => r.countries?.includes(c)); navigate(`/${r ? r.id : ""}/${slugify(c)}`); };
  const goToDish        = (d)   => {
    // d may be a display name like "Pan-Fried Barramundi" or a DB key like "Barramundi"
    // Find the actual DB key by checking both direct match and name match
    const key = RECIPE_DB[d] ? d : Object.keys(RECIPE_DB).find(k => RECIPE_DB[k].name === d || slugify(RECIPE_DB[k].name) === slugify(d)) || d;
    if (!RECIPE_DB[key]) return; // recipe not yet available
    const country = RECIPE_DB[key]?.country;
    const r = REGIONS.find(r => r.countries?.includes(country));
    navigate(`/${r ? r.id : ""}/${slugify(country || "")}/${slugify(RECIPE_DB[key]?.name || key)}`);
  };
  const goToRegions     = ()    => navigate('/');
  const goToRegionBack  = ()    => navigate(selectedRegion ? `/${selectedRegion}` : '/');
  const goToCountryBack = ()    => navigate(selectedRegion && selectedCountry ? `/${selectedRegion}/${slugify(selectedCountry)}` : selectedRegion ? `/${selectedRegion}` : '/');

  const region = REGIONS.find(r => r.id === selectedRegion);

  return (
    <>
      <style>{styles}</style>
      <div style={{ minHeight:"100vh", background:"#fdfcf9" }}>
        {/* Header */}
        <div style={{ background:"#fff", borderBottom:"1.5px solid #ece6db", padding:"13px 28px", display:"flex", alignItems:"center", justifyContent:"space-between", flexWrap:"wrap", gap:12, position:"sticky", top:0, zIndex:50, boxShadow:"0 1px 8px rgba(0,0,0,.05)" }}>
          <div style={{ cursor:"pointer", display:"flex", alignItems:"center", gap:12 }} onClick={goToRegions}>
            <div style={{ width:36, height:36, background:"linear-gradient(135deg,#c2622a,#e8832a)", borderRadius:10, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0, boxShadow:"0 2px 8px rgba(194,98,42,.35)" }}>
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <circle cx="14" cy="12" r="8" stroke="#fff" strokeWidth="1.8" fill="none"/>
                <path d="M6 12 Q14 8 22 12" stroke="#fff" strokeWidth="1.4" fill="none"/>
                <path d="M6 12 Q14 16 22 12" stroke="#fff" strokeWidth="1.4" fill="none"/>
                <line x1="14" y1="4" x2="14" y2="20" stroke="#fff" strokeWidth="1.4"/>
                <line x1="3" y1="4" x2="3" y2="20" stroke="#fff" strokeWidth="2" strokeLinecap="round"/>
                <line x1="1" y1="4" x2="1" y2="9" stroke="#fff" strokeWidth="1.6" strokeLinecap="round"/>
                <line x1="5" y1="4" x2="5" y2="9" stroke="#fff" strokeWidth="1.6" strokeLinecap="round"/>
                <path d="M1 9 Q3 13 5 9" stroke="#fff" strokeWidth="1.6" fill="none"/>
              </svg>
            </div>
            <div>
              <div style={{ fontFamily:"Fraunces", fontSize:18, fontWeight:700, color:"#1a1714" }}>Recipe Atlas</div>
              <div style={{ fontSize:10, color:"#b8b0a8", letterSpacing:".1em", textTransform:"uppercase", fontWeight:500 }}>World Cuisine Explorer</div>
            </div>
          </div>
          {view !== "regions" && (
            <div style={{ display:"flex", alignItems:"center", gap:6, fontSize:12, color:"#b8b0a8", flexWrap:"wrap" }}>
              {view === "recipe" && recipeCountry ? (
                <>
                  <span style={{ cursor:"pointer", color:"#9a9088", fontWeight:500 }} onClick={() => { const r = REGIONS.find(r => r.countries?.includes(recipeCountry)); navigate(`/${r ? r.id : ""}/${slugify(recipeCountry)}`); }}>{recipeCountry}</span>
                  {selectedDish && <><span>›</span><span style={{ color:"#1a1714", fontWeight:600 }}>{selectedDish}</span></>}
                </>
              ) : (
                <>
                  <span style={{ cursor:"pointer", color:"#9a9088", fontWeight:500 }} onClick={goToRegions}>Regions</span>
                  {selectedRegion && <><span>›</span><span style={{ cursor:"pointer", color: view!=="region"?"#9a9088":"#1a1714", fontWeight:500 }} onClick={goToRegionBack}>{region?.name}</span></>}
                  {!selectedRegion && countryRegion && <><span>›</span><span style={{ cursor:"pointer", color:"#9a9088", fontWeight:500 }} onClick={() => navigate(`/${countryRegion.id}`)}>{countryRegion.name}</span></>}
                  {selectedCountry && <><span>›</span><span style={{ cursor:"pointer", color: view!=="country"?"#9a9088":"#1a1714", fontWeight:500 }} onClick={goToCountryBack}>{selectedCountry}</span></>}
                  {selectedDish && <><span>›</span><span style={{ color:"#1a1714", fontWeight:600 }}>{selectedDish}</span></>}
                </>
              )}
            </div>
          )}
        </div>

        {/* Main */}
        <div style={{ position:"relative", backgroundImage:"url(https://images.pexels.com/photos/13832265/pexels-photo-13832265.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1)", backgroundSize:"cover", backgroundPosition:"center", backgroundAttachment:"fixed" }}>
          <div style={{ position:"absolute", inset:0, background:"rgba(253,252,249,0.92)", mixBlendMode:"normal" }} />
          <div style={{ position:"relative", zIndex:1 }}>
        {!["blog","about","contact","privacy","terms"].includes(view) && (
          <div style={{ padding:"32px 24px 60px", maxWidth:960, margin:"0 auto" }}>
            {view === "regions"  && <RegionMap onSelectRegion={goToRegion} />}
            {view === "region"   && selectedRegion && <RegionView regionId={selectedRegion} onBack={goToRegions} onSelectCountry={goToCountry} />}
            {view === "country"  && selectedCountry && <CountryView country={selectedCountry} onBack={goToRegionBack} onSelectDish={goToDish} />}
            {view === "recipe"   && selectedDish && <RecipeView country={recipeCountry || selectedCountry} dish={selectedDish} navigate={navigate} onBack={() => { const r = REGIONS.find(r => r.countries?.includes(recipeCountry)); navigate(recipeCountry && r ? `/${r.id}/${slugify(recipeCountry)}` : '/'); }} />}
            {(view === "region" && !selectedRegion) && <RegionMap onSelectRegion={goToRegion} />}
            {(view === "country" && !selectedCountry) && <RegionMap onSelectRegion={goToRegion} />}
            {(view === "recipe" && !selectedDish) && <RegionMap onSelectRegion={goToRegion} />}
          </div>
        )}

        {/* Info pages */}
        {["blog","about","contact","privacy","terms"].includes(view) && (
          <div style={{ padding:"32px 24px 60px", maxWidth:960, margin:"0 auto" }}>
            <div style={{ maxWidth:680, margin:"0 auto 32px" }}>
              <AdUnit />
            </div>
            {view === "blog" && <BlogPage navigate={navigate} initialSlug={parts[1] || null} />}
            {view === "about" && <AboutPage />}
            {view === "contact" && <ContactPage />}
            {view === "terms" && <TermsPage />}
            {view === "privacy" && <PrivacyPage />}
          </div>
        )}

          </div>
        </div>
        {/* Footer */}
        <div style={{ borderTop:"1.5px solid #ece6db", padding:"28px", background:"#fdfcf9" }}>
          <div style={{ maxWidth:960, margin:"0 auto" }}>
            <div style={{ display:"flex", flexWrap:"wrap", justifyContent:"space-between", alignItems:"center", gap:16, marginBottom:16 }}>
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                <svg width="22" height="22" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <circle cx="14" cy="12" r="8" stroke="#c2622a" strokeWidth="1.8" fill="none"/>
                  <path d="M6 12 Q14 8 22 12" stroke="#c2622a" strokeWidth="1.4" fill="none"/>
                  <path d="M6 12 Q14 16 22 12" stroke="#c2622a" strokeWidth="1.4" fill="none"/>
                  <line x1="14" y1="4" x2="14" y2="20" stroke="#c2622a" strokeWidth="1.4"/>
                  <line x1="3" y1="4" x2="3" y2="20" stroke="#c2622a" strokeWidth="2" strokeLinecap="round"/>
                  <line x1="1" y1="4" x2="1" y2="9" stroke="#c2622a" strokeWidth="1.6" strokeLinecap="round"/>
                  <line x1="5" y1="4" x2="5" y2="9" stroke="#c2622a" strokeWidth="1.6" strokeLinecap="round"/>
                  <path d="M1 9 Q3 13 5 9" stroke="#c2622a" strokeWidth="1.6" fill="none"/>
                </svg>
                <div>
                  <div style={{ fontFamily:"Fraunces", fontSize:15, fontWeight:700, color:"#1a1714" }}>Recipe Atlas</div>
                  <div style={{ fontSize:10, color:"#b8b0a8", letterSpacing:".1em", textTransform:"uppercase" }}>World Cuisine Explorer</div>
                </div>
              </div>
              <div style={{ display:"flex", gap:20, flexWrap:"wrap" }}>
                {[["blog","Blog"],["about","About"],["contact","Contact"],["privacy","Privacy"],["terms","Terms"]].map(([v,label]) => (
                  <span key={v} onClick={() => navigate(`/${v}`)}
                    style={{ fontSize:12, color:"#9a9088", cursor:"pointer", fontWeight:500, fontFamily:"Plus Jakarta Sans" }}>
                    {label}
                  </span>
                ))}
              </div>
            </div>
            <div style={{ borderTop:"1px solid #ece6db", paddingTop:16, display:"flex", flexWrap:"wrap", justifyContent:"space-between", gap:8 }}>
              <span style={{ fontSize:11, color:"#c8bfb0", fontFamily:"Plus Jakarta Sans" }}>© {new Date().getFullYear()} Recipe Atlas. All rights reserved.</span>
              <span style={{ fontSize:11, color:"#c8bfb0", fontFamily:"Plus Jakarta Sans" }}>Celebrating food from every corner of the world.</span>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

